return items.map(item => {
        const email = item.json;
        const subject = email.subject || "";
        const body = email.bodyPreview || email.body || "";
        const sender = email.from || "";
        const messageId = email.id || "";
        const emailText = `Objet: ${subject}
Expéditeur: ${sender}
Message:
${body}`;
        return {
          json: {
            messageId,
            subject,
            sender,
            body,
            emailText
          }
        };
      });

