parameters.jsCode:
return items.map(item => {
  const parsed = JSON.parse(item.json.response);
  const classification = parsed.classifications?.[0] || {};
  return {
    json: {
      requestType: classification.requestType || "",
      requestSubType: classification.requestSubType?.[0] || "",
      confidenceScore: parsed.confidenceScore || null,
      reasoning: parsed.reasoning || "",
      outlookCategory: classification.requestType || "Other"
    }
  };
});
